const db = require('better-sqlite3')('/workspace/world.db');
// Search across likely tables for A58410
const tables = ['hotel_reservations','flight_bookings','car_rentals','orders'];
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM ' + t + \" WHERE reservation_id LIKE '%A58410%' OR booking_id LIKE '%A58410%' OR rental_id LIKE '%A58410%' OR order_id LIKE '%A58410%'\").all().catch ? [] : [];
}
// Just do a raw text search
const allTables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of allTables) {
  try {
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
    for (const c of cols) {
      try {
        const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE CAST(' + c.name + ' AS TEXT) LIKE ?').all('%A58410%');
        if (rows.length > 0) {
          console.log('Found in', t.name, '.', c.name, ':');
          console.log(JSON.stringify(rows, null, 2));
        }
      } catch(e) {}
    }
  } catch(e) {}
}
"

